  'Coro in blue': { de: 'Coro in Blau', fr: 'Coro en bleu', es: 'Coro de azul', ja: 'あおい ふくの コロ', ar: 'كورو بالأزرق' },
  'Coro writing': { de: 'Coro schreibt', fr: 'Coro écrit', es: 'Coro escribe', ja: 'かいている コロ', ar: 'كورو يكتب' },
  'Coro cheering': { de: 'Coro jubelt', fr: 'Coro applaudit', es: 'Coro celebra', ja: 'よろこぶ コロ', ar: 'كورو يهتف' },
  'Unicorn': { de: 'Einhorn', fr: 'Licorne', es: 'Unicornio', ja: 'ユニコーン', ar: 'يونيكورن' },
